app.MapGet("/api/orders", async (
    string? cursor, int? limit, OrderDb db, CancellationToken ct) =>
{
    var take = Math.Clamp(limit ?? 20, 1, 100);   // never let clients pick unbounded pages

    var q = db.Orders.AsNoTracking();
    if (cursor is not null)
    {
        var (at, id) = Cursor.Decode(cursor);      // base64url + HMAC if untrusted
        q = q.Where(o => o.CreatedAt < at || (o.CreatedAt == at && o.Id < id));
    }

    var rows = await q.OrderByDescending(o => o.CreatedAt)
        .ThenByDescending(o => o.Id)               // tiebreaker — mandatory
        .Take(take + 1)                            // fetch one extra to detect "has more"
        .ToListAsync(ct);

    var hasMore = rows.Count > take;
    if (hasMore) rows.RemoveAt(rows.Count - 1);
    var next = hasMore ? Cursor.Encode(rows[^1].CreatedAt, rows[^1].Id) : null;

    return Results.Ok(new OrderPage(rows, next));
});

// "But users want page numbers!" — options:
// 1) Bound the depth: free navigation to page 20, keyset beyond (deep links via cursor).
// 2) Estimated counts + keyset: show 'Page ~500 of ~2400', still seek on navigation.
// 3) If arbitrary jumps are truly required, accept OFFSET for that path ONLY,
//    bound it, and serve the common sequential/infinite-scroll path with keyset.
